        ["ButcherYoung_Greetings"] = "Nitko se ne usudi sumnjati u moj autoritet! Obitelj to ne oprašta. Nećeš odavde živ izaći!",
        ["Butcher_zone3_1"] = "Vratio se izgubljeni sin! Jesi li razmislio o mom prijedlogu, Kneže? Pustim te, kažem gdje je Sfera, a ti mi platiš zlatom?",
        ["Butcher_zone3_2"] = "Njegova šutnja govori više od riječi, starče. Ja sam iskren sa sobom, prihvatio sam svoju zvjersku narav. On nije. Ali naučit ćemo vas mi poniznosti. Djeco, k meni!",
        ["Guard1_Butcher_Sensei"] = "Mesar mi je pokazao kako bol otkriva našu pravu bit. Sad sam slobodna! I vi ćete naći sreću. Ne oppirite se!",
        ["Guard1_Hermit_Sensei"] = "Promjene dolaze! Prešla sam pola svijeta da to shvatim, žrtvovala sam toliko mnogo... I učiteljeva mudrost — to je sve što mi ostaje!",
        ["Guard1_Lynx_Sensei"] = "Sviđaju ti se moji uzorci? Ondje odakle potječem, tetoviraju ih najjačima u spomen na ratne podvige. Sad ćeš i ti postati dio mog crteža...",
        ["Guard1_Wasp_Sensei"] = "Vjeruješ li u sreću? Mislim da će mi danas posebno posrećiti — uzet ću sav tvoj novac! Hoće li tebi posrećiti, starče?",
        ["Guard1_Widow_Sensei"] = "Gospodarica mi je poput sestre. Dobro osjećam njenu bol. Zabranila mi je dirati Kneza, pa će moj gnjev pasti na tebe!",
        ["Guard2_Butcher_Sensei"] = "Plijen sam dolazi grabežljivcu! Filozofija je za pametne, a ja jednostavno volim igrati se noževima. Hoćete li se igrati sa mnom?!",
        ["Guard2_Hermit_Sensei"] = "Učitelj je pričao o svijetu sjena, njegovim stanovnicima i nevjerojatnoj moći kojom će se podijeliti s nama. Misliš li da ću to dopustiti da nam se uzme?",
        ["Guard2_Lynx_Sensei"] = "Naš klan radi posao kojim se ni bogovi ne žele prljati. Mi rješavamo probleme i ispravljamo tuđe greške. I ti si jedna od njih.",
        ["Guard2_Wasp_Sensei"] = "Prijetiš mojoj kapetanici? Ona me spasila iz ropstva, i zaklela sam se da ću odraditi svoju slobodu. Neka ti duhovi budu milostivi...",
        ["Guard2_Widow_Sensei"] = "Moja gospodarica je prekrasna! Nisam bio dostojan gledati u njezino lice... Sada moj život pripada njoj. Branit ću njezinu čast do posljednjeg daha.",
        ["HermitYoung_Greetings"] = "Kneže, vi ste žrtva okolnosti. Trebalo je prinijeti tu žrtvu za opće dobro. Moja škola postat će velika, i nastupit će zlatno doba borilačkih vještina!",
        ["Hermit_zone2_1"] = "Našli ste se između čekića i nakovnja, gospodine. Da, izdao sam vas. Nisam imao izbora, jer u igri je budućnost moje škole.",
        ["Hermit_zone2_2"] = "Taj oholI mladić Ris nije uspio izvršiti svoju zadaću. Izgleda da ću morati obaviti posao umjesto njega. Učenici, ovamo!",
        ["LynxYoung_Greetings"] = "Ne mogu tek tako otići. Već sam uzeo novac za Knežev život. Ništa osobno, starče.",
