        ["TITLE_PRINCE_EVIL"] = "UKLETI PRINC",
        ["WaspYoung_Greetings"] = "Što ću reći svom ocu? Da je njegova kći omekšala i izgubila borbu od nekog starca? To se neće dogoditi dok sam ja nasljednica gusarskog prijestolja!",
        ["Wasp_zone4_1"] = "Udovica te poslala po Sferu? Nisi li malo star za takve zadatke? Mada, svejedno mi je. Ukrcaj se.",
        ["Wasp_zone4_2"] = "Samo što Sfere više nemam. Udovičini ljudi su je uzeli još jučer. Ne znam tko si, ali laž ne opraštam. Provucite ga pod kobilicom!",
        ["WidowYoung_Greetings"] = "Knez me je ponizio, odbio me, narugao se mojim osjećajima. I sad ću uzvratiti udarac! Ti si njegov prijatelj, pa ćeš mu prenijeti ovu poruku...",
        ["Widow_zone5_1"] = "I ti si došao da me ponizis, kao i Knez? Vi, muškarci, svi ste isti...",
