    },
    por = {
        ["ActScreenSensei1"] = "A História do Sensei{br}Parte 1. A Testemunha",
        ["ActScreenSensei2"] = "A História do Sensei{br}Parte 2. A Sombra do Futuro",
        ["ActScreenSensei3"] = "A História do Sensei{br}Parte 3. A Besta Interior",
        ["ActScreenSensei4"] = "A História do Sensei{br}Parte 4. A História da Vingança",
        ["ActScreenSensei5"] = "A História do Sensei{br}Parte 5. Humilhada e Ofendida",
        ["ActScreenSensei6"] = "A História do Sensei{br}Parte 6. O Monstro",
        ["ButcherYoung_Greetings"] = "Ninguém ousa duvidar de minha autoridade! A família nunca se esquece disso. Você não sairá daqui vivo!",
        ["Butcher_zone3_1"] = "Ah, o bom filho à casa torna! Reconsiderou minha proposta, Príncipe? Aquela que, se eu o deixasse ir e contasse a localização da Esfera, você me recompensaria com ouro?",
        ["Butcher_zone3_2"] = "O silêncio dele é maior que qualquer palavra, meu velho. Eu sou honesto comigo mesmo, assumindo minha natureza bestial. Ele, não. Mas vamos lhe ensinar humildade! Venham, crianças!",
        ["Guard1_Butcher_Sensei"] = "O Açougueiro me mostrou como a dor revela nosso eu verdadeiro, e agora sou livre! Você também pode encontrar a felicidade. Não resista!",
        ["Guard1_Hermit_Sensei"] = "A mudança é iminente! Cruzei metade do mundo para aprender isso e sacrifiquei muito... A sabedoria do Mestre é tudo o que tenho!",
        ["Guard1_Lynx_Sensei"] = "Gostou das minhas tatuagens? Na terra onde nasci, o mais forte ganha isso como lembrancinha de seus grandes feitos. Em breve, você também estará aqui no desenho...",
        ["Guard1_Wasp_Sensei"] = "Tu acredita em sorte? Porque hoje vou tirar a sorte grande, fazendo uma fortuna com teu dinheiro. Tá se achando sortudo, velho?",
        ["Guard1_Widow_Sensei"] = "Minha senhora é como uma irmã para mim. Posso sentir sua dor. Mas ela me proíbe de tocar num fio de cabelo sequer do Príncipe, então minha ira será direcionada a você!",
        ["Guard2_Butcher_Sensei"] = "Esse jogo já está ganho! Filosofia é para trouxas! Já eu, meu lance é brincar com facas. Quer brincar comigo?",
        ["Guard2_Hermit_Sensei"] = "O Mestre nos contou sobre o Mundo das Sombras, seus habitantes e os poderes imediatos que vai dividir conosco. Acha que vou deixar você tirar isso de nós?",
        ["Guard2_Lynx_Sensei"] = "Nosso clã faz o trabalho sujo, aquele que é sujo demais até para os deuses, sabe? Solucionamos os problemas e corrigimos os erros dos outros... erros como você.",
        ["Guard2_Wasp_Sensei"] = "Você está ameaçando minha capitã? Ela me salvou da escravidão e eu jurei trabalhar por minha liberdade. Que os espíritos tenham misericórdia de ti...",
        ["Guard2_Widow_Sensei"] = "Minha senhora é tão justa! Não sou digno de ver seu rosto... Agora minha vida pertence a ela, e vou protegê-la até meu último suspiro.",
        ["HermitYoung_Greetings"] = "Você é uma vítima das circunstâncias, Príncipe, um sacrifício para o bem comum. Minha escola deve conquistar a grandeza e, então, a era de ouro das artes marciais terá seu início!",
        ["Hermit_zone2_1"] = "Você está entre a cruz e a espada, meu senhor! Eu admito que o traí. Mas não tive escolha, pois o futuro da minha escola está em risco.",
        ["Hermit_zone2_2"] = "Lince, esse jovem arrogante, não cumpriu sua tarefa. Terei eu mesmo que fazer seu trabalho. Discípulos, em frente!",
        ["LynxYoung_Greetings"] = "Eu não posso partir, já me pagaram pela vida do Príncipe. Nada pessoal, meu velho.",
        ["Lynx_Sensei_1"] = "Não dê ouvidos ao Príncipe, velho! Ele enlouqueceu. Vamos levar Sua Alteza para casa antes que ele se machuque. Sua ajuda não é exigida no momento.",
        ["Lynx_Sensei_2"] = "Sério? Porque, tudo que vejo, é um homem assustado e cercado por assassinos cruéis. Algo me diz que o Príncipe está dizendo a verdade. Afastem-se dele!",
        ["Lynx_Sensei_3"] = "Faça o que quiser, eles não me pagam para bater papo. E duas cabeças significam mais dinheiro. Peguem-no, homens!",
        ["NAME_BUTCHER"] = "AÇOUGUEIRO",
        ["NAME_HERMIT"] = "EREMITA",
        ["NAME_LYNX"] = "LINCE",
        ["NAME_PRINCE"] = "PRÍNCIPE",
        ["NAME_SHOGUN"] = "SHOGUN",
        ["NAME_WASP"] = "VESPA",
        ["NAME_WIDOW"] = "VIUVA",
        ["OK"] = "OK",
        ["Prince_Intro"] = "Socorro! Essas pessoas querem me matar!",
        ["Prince_zone3_1"] = "Como ousa manchar meu nome?! Seu... seu desgraçado! Vou acabar com seu reino de crueldades!",
        ["Prince_zone6_1"] = "Ah, aqui está você, amigo leal! Veja, a justiça triunfa novamente, Shogun é meu fiel cãozinho. Agora sua mente é minha!",
        ["Prince_zone6_2"] = "Você também, velho? Quer tomar meu trono?! Ele é meu por direito de nascença! Ninguém vai tomá-lo de mim!",
        ["Sensei_arc_intro1"] = "Muito tempo atrás, caminhava eu por aí, quando me deparei com o senhor regional, totalmente apavorado...",
        ["Sensei_zone3_1"] = "Então é isso que você chama de “sorte”? Comprar sua liberdade e entregar seus homens de bandeja para uma gangue de lunáticos... E eu fui tão gentil com você, Príncipe!",
        ["Sensei_zone4_1"] = "Viúva? Claro... Ela me disse para apanhar a Esfera e levá-la para o Shogun, entregá-la em mãos.",
        ["Sensei_zone6_1"] = "Príncipe, pare! Olhe ao redor! A Esfera está se alimentando de sua raiva, transformando você num monstro!",
        ["Shogun_zone6_1"] = "Seu fraco! Você não é bom nem para ser o bobo da corte de meu senhor. Vou destruí-lo com um único golpe!",
        ["TITLE_PRINCE_EVIL"] = "PRÍNCIPE ASSOMBRADO",
        ["WaspYoung_Greetings"] = "O que vou dizer a meu pai? Sua filha teve uma crise histérica e perdeu a briga contra um velho? Isso não vai acontecer enquanto eu for a herdeira do trono dos piratas!",
        ["Wasp_zone4_1"] = "A Viúva te enviou para apanhar a Esfera? Tu não é meio velho para esse trabalho, não? Ah, que se dane. Sobe aí, então.",
        ["Wasp_zone4_2"] = "Só que eu não estou mais com a Esfera, porque os homens da Viúva levaram ontem. Não sei quem é você, mas mentirosos não passarão! Keelhaul ‘im!",
        ["WidowYoung_Greetings"] = "O Príncipe me humilhou quando me rejeitou e riu de meus sentimentos. Agora vou atacar de volta! Vocês são amigos dele, então vão entregar essa mensagem para ele...",
        ["Widow_zone5_1"] = "Você veio me humilhar como o Príncipe fez? Vocês machos são todos iguais...",
        ["Widow_zone5_2"] = "Ele me contou sobre sua gentileza, honra e dignidade. Mas eu não acredito mais nas palavras dos homens. Todos você devem sofrer!",
        ["Zone2_SenseiReminder"] = "Da última vez, contava como salvei o Príncipe dos assassinos. Eu descobri que o Eremita estava treinando seus soldados secretamente, então foi para lá que me dirigi.",
        ["Zone3_SenseiReminder"] = "O Eremita nos contou que o Shogun, o senhor da guerra do Príncipe, havia traído seu senhor e pagado a um tal de Açougueiro para sequestrá-lo. Era hora de visitar o tal bandido.",
        ["Zone4_SenseiReminder"] = "Os problemas do Príncipe foram causados por uma mulher! Ela tramou um plano para destroná-lo com o auxílio de uma Esfera mágica, que, então, havia sido trazido para um porto próximo dali...",
        ["Zone5_SenseiReminder"] = "A pirata me contou a história complicada da Viúva com o Príncipe. Não consegui apanhar a Esfera, mas descobri que o Príncipe havia partido para as montanhas para encontrar a Viúva.",
        ["Zone6_SenseiReminder"] = "A Esfera mágica enlouqueceu o Príncipe! Deu-lhe um poder imediato... que ameaçava destruir todos nós! Eu não podia permitir isso.",
        ["characterSensei"] = "SENSEI",
        ["character_Asian"] = "LÓTUS",
        ["character_Blind"] = "FURÃO",
        ["character_Fanatic"] = "NAVALHA",
        ["character_Indean"] = "PUMA",
        ["character_Philosopher"] = "CLÉRIGO",
        ["character_Pirate"] = "PIRATA",
        ["character_Ronin"] = "ARAUTO",
        ["character_Sadist"] = "TORMENTA",
        ["character_Savage"] = "CENTELHA",
        ["character_Sister"] = "ASTRA",
        ["dlgStoryBtnFight"] = "LUTE",
    },
    rom = {
        ["ActScreenSensei1"] = "Povestea lui Sensei{br}Partea 1. Martorul",
        ["ActScreenSensei2"] = "Povestea lui Sensei{br}Partea 2. Umbra Viitorului",
        ["ActScreenSensei3"] = "Povestea lui Sensei{br}Partea 3. Bestia din Interior",
        ["ActScreenSensei4"] = "Povestea lui Sensei{br}Partea 4. Povestea Răzbunării",
        ["ActScreenSensei5"] = "Povestea lui Sensei{br}Partea 5. Umiliţi și Jigniţi",
        ["ActScreenSensei6"] = "Povestea lui Sensei{br}Partea 6. Monstrul",
        ["ButcherYoung_Greetings"] = "Nimeni nu îndrăznește să se îndoiască de autoritatea mea! Familia nu iartă niciodată asta. Nu vei pleca de-aici în viaţă!",
        ["Butcher_zone3_1"] = "Fiul risipitor se întoarce! Te-ai gândit la propunerea mea, Prinţule? Te las să pleci și îţi spun unde este Sfera, iar tu mă plătești în aur.",
        ["Butcher_zone3_2"] = "Tăcerea lui este mai asurzitoare decât cuvintele, bătrâne. Eu? Eu sunt sincer cu mine însumi — îmi accept natura bestială. El nu. Dar vă vom învăţa umilinţa! Veniţi, copiii mei!",
        ["Guard1_Butcher_Sensei"] = "Măcelarul mi-a arătat cum durerea ne dezvăluie adevăratul sine. Acum sunt liber! Și tu poţi găsi fericirea. Nu te împotrivi!",
        ["Guard1_Hermit_Sensei"] = "Schimbarea este iminentă! Am străbătut jumătate de lume pentru a o învăţa, am sacrificat atât de mult... Înţelepciunea Maestrului este tot ce am!",
        ["Guard1_Lynx_Sensei"] = "Îţi plac tatuajele mele? În ţinutul în care m-am născut, cei mai puternici le primesc ca amintiri ale isprăvilor lor. În curând vei face și tu parte din tablou...",
        ["Guard1_Wasp_Sensei"] = "Crezi în noroc? Cred că azi îmi voi face norocul luându-ţi toţi banii. Crezi că vei avea noroc, bătrâne?",
        ["Guard1_Widow_Sensei"] = "Doamna mea îmi este ca o soră. Îi simt durerea. Ea îmi interzice să mă ating de Prinţ, așa că mânia mea va cădea asupra ta!",
        ["Guard2_Butcher_Sensei"] = "Jocul e ca și câștigat! Filozofia e pentru tocilari — mie îmi place doar să mă joc cu cuţitele. Vrei să te joci cu mine?",
        ["Guard2_Hermit_Sensei"] = "Maestrul ne-a povestit despre lumea umbrelor — despre locuitorii ei și puterea imensă pe care o va împărţi cu noi. Crezi că te voi lăsa să ne iei toate acestea?",
        ["Guard2_Lynx_Sensei"] = "Clanul nostru face o treabă care e prea murdară chiar și pentru zei. Noi rezolvăm probleme și corectăm greșelile altora. Iar tu — tu ești una dintre acele greșeli.",
        ["Guard2_Wasp_Sensei"] = "Îmi ameninţi căpitanul? M-a salvat din sclavie, iar eu am jurat să-mi răscumpăr libertatea prin muncă. Fie ca spiritele să fie blânde cu tine...",
        ["Guard2_Widow_Sensei"] = "Doamna mea este atât de frumoasă! Am fost nedemn să-i văd chipul... Acum viaţa mea îi aparţine. Îi voi proteja onoarea până la ultima mea suflare.",
        ["HermitYoung_Greetings"] = "Ești o victimă a circumstanţelor, Prinţule — un sacrificiu necesar pentru binele comun. Școala mea va atinge măreţia, iar epoca de aur a artelor marţiale va începe!",
        ["Hermit_zone2_1"] = "Ești între ciocan și nicovală, stăpâne. Recunosc — te-am trădat. Nu am avut de ales, totuși — viitorul școlii mele este în joc.",
        ["Hermit_zone2_2"] = "Lynx, acel tânăr arogant, nu s-a descurcat cu sarcina sa. Va trebui să-i fac eu treaba. Discipoli, adunarea!",
        ["LynxYoung_Greetings"] = "Nu pot să plec pur și simplu. Am fost deja plătit pentru viaţa Prinţului. Nimic personal, bătrâne.",
        ["Lynx_Sensei_1"] = "Nu-l asculta pe Prinţ, bătrâne — doar și-a pierdut minţile. Îl ducem pe Alteţa Sa acasă înainte să se rănească. Nu este nevoie de ajutorul tău.",
        ["Lynx_Sensei_2"] = "Într-adevăr? De unde stau eu, văd un om înspăimântat înconjurat de ucigași. Ceva îmi spune că Prinţul spune adevărul. Îndepărtaţi-vă de el!",
        ["Lynx_Sensei_3"] = "Fă ce vrei. Nu sunt plătit ca să vorbesc. Două capete înseamnă mai mulţi bani. Luaţi-i, băieţi!",
        ["NAME_BUTCHER"] = "MĂCELAR",
        ["NAME_HERMIT"] = "PUSTNIC",
        ["NAME_LYNX"] = "LYNX",
        ["NAME_PRINCE"] = "PRINŢ",
        ["NAME_SHOGUN"] = "SHOGUN",
        ["NAME_WASP"] = "VIESPE",
        ["NAME_WIDOW"] = "VĂDUVĂ",
        ["OK"] = "OK",
        ["Prince_Intro"] = "Ajutor! Oamenii aceștia vor să mă omoare!",
        ["Prince_zone3_1"] = "Cum îndrăznești să-mi murdărești numele! Tu... ticălos mizerabil! M-am întors să pun capăt domniei tale pline de cruzime!",
        ["Prince_zone6_1"] = "Iată-te, prietenul meu loial! Privește — dreptatea triumfă din nou. Shogun este câinele meu credincios. Mintea lui e a mea!",
        ["Prince_zone6_2"] = "Și tu, bătrâne? Vrei să-mi iei tronul?! Îl deţin prin drept din naștere! Nimeni nu mi-l va lua!",
        ["Sensei_arc_intro1"] = "A fost odată ca niciodată, mă plimbam și m-am întâlnit cu lordul local — era într-o mare suferinţă...",
        ["Sensei_zone3_1"] = "Deci asta înseamnă „noroc”? Să-ţi cumperi libertatea și să-ţi dai oamenii pe mâna unei bande de nebuni... Și eu am fost atât de bun cu tine, Prinţule.",
        ["Sensei_zone4_1"] = "Văduva? Desigur... ea mi-a spus să iau Sfera și să i-o aduc lui Shogun — chiar în mâinile lui.",
        ["Sensei_zone6_1"] = "Prinţule, oprește-te! Privește în jur! Sfera se hrănește cu furia ta, transformându-te într-un monstru!",
        ["Shogun_zone6_1"] = "Slăbănogule! Nici măcar nu ești destul de bun pentru a fi bufonul curţii lordului meu. Te voi zdrobi cu o singură lovitură!",
        ["TITLE_PRINCE_EVIL"] = "PRINŢUL BÂNTUIT",
        ["WaspYoung_Greetings"] = "Ce ar trebui să-i spun tatălui meu? Că fiica lui s-a muiat și a pierdut o luptă în faţa unui moșneag? Asta n-o să se întâmple atâta timp cât sunt moștenitoarea tronului piraţilor!",
        ["Wasp_zone4_1"] = "Văduva te trimite să iei Sfera? Nu ești cam bătrân pentru astfel de treburi? Ah, de ce mi-ar păsa? Urcă la bord.",
        ["Wasp_zone4_2"] = "Chestia e că nu mai am Sfera. Oamenii Văduvei au luat-o ieri. Nu știu cine ești, dar nu iert niciodată mincinoșii. Treceţi-l pe sub chilă!",
        ["WidowYoung_Greetings"] = "Prinţul m-a umilit — m-a respins, a râs de sentimentele mele. Acum voi lovi și eu! Ești prietenul lui, așa că îi vei transmite acest mesaj...",
        ["Widow_zone5_1"] = "Ai venit să mă umilești la fel cum a făcut-o Prinţul? Voi, masculii, sunteţi toţi la fel...",
        ["Widow_zone5_2"] = "Mi-a tot povestit despre bunătatea, onoarea și demnitatea ta. Dar nu mai cred cuvintele niciunui mascul. Fiecare dintre voi va suferi!",
        ["Zone2_SenseiReminder"] = "Ultima dată, ţi-am povestit cum l-am salvat pe Prinţ de asasini. Am aflat că Pustnicul își antrena soldaţii în secret. Așa că acolo ne-am dus.",
        ["Zone3_SenseiReminder"] = "Pustnicul ne-a spus că lordul de război al Prinţului, Shogun, și-a trădat stăpânul și a plătit un anume Măcelar să-l răpească. Era timpul să-l vizităm pe bandit.",
        ["Zone4_SenseiReminder"] = "Problemele Prinţului au fost cauzate de o femeie! Ea a pus la cale un plan pentru a-l răsturna folosind o Sferă magică — care acum era adusă în portul din apropiere...",
        ["Zone5_SenseiReminder"] = "Fata pirat mi-a povestit despre istoria complicată a Văduvei cu Prinţul. Nu am obţinut Sfera, dar am aflat că Prinţul s-a dus la munte să o găsească pe Văduvă.",
        ["Zone6_SenseiReminder"] = "Sfera magică l-a înnebunit pe Prinţ! I-a oferit o putere imensă... o putere care ameninţa să ne distrugă pe toţi! Nu puteam permite să se întâmple asta.",
        ["characterSensei"] = "SENSEI",
        ["character_Asian"] = "LOTUS",
        ["character_Blind"] = "ERMINE",
        ["character_Fanatic"] = "BICIUL",
        ["character_Indean"] = "COUGAR",
        ["character_Philosopher"] = "CLERICUL",
        ["character_Pirate"] = "PIRAT",
        ["character_Ronin"] = "PREVESTITORUL",
        ["character_Sadist"] = "TORŢIONARUL",
        ["character_Savage"] = "SCÂNTEIE",
        ["character_Sister"] = "ASTER",
        ["dlgStoryBtnFight"] = "LUPTĂ!",
    },
    rus = {
        ["ActScreenSensei1"] = "История Сэнcея{br}Часть 1: \"Свидетель\"",
        ["ActScreenSensei2"] = "История Сэнcея{br}Часть 2: \"Тень грядущего\"",
        ["ActScreenSensei3"] = "История Сэнcея{br}Часть 3: \"Зверь внутри\"",
        ["ActScreenSensei4"] = "История Сэнcея{br}Часть 4: \"История мести\"",
        ["ActScreenSensei5"] = "История Сэнcея{br}Часть 5: \"Униженная и {br}оскорбленная\"",
        ["ActScreenSensei6"] = "История Сэнcея{br}Часть 6: \"Чудовище\"",
        ["ButcherYoung_Greetings"] = "Никто не смеет ставить мой авторитет под сомнение! Семья не прощает этого. Ты не уйдешь отсюда живым!",
        ["Butcher_zone3_1"] = "Блудный сын вернулся! Ты обдумал мое предложение, Князь: я отпускаю тебя, говорю, где магическая Сфера, а ты платишь мне золотом?",
        ["Butcher_zone3_2"] = "Его молчание громче слов, старик. Я честен с собой, принял свою животную натуру. А он — нет. Но мы научим вас смирению. Дети, ко мне!",
        ["Guard1_Butcher_Sensei"] = "Мясник показал мне, как боль открывает нашу истинную сущность. Теперь я свободна! Вы тоже обретете счастье. Не сопротивляйтесь!",
        ["Guard1_Hermit_Sensei"] = "Грядут перемены! Я пересекла половину мира, чтобы понять это, столь многим пожертвовала... И мудрость учителя — это все, что у меня есть!",
        ["Guard1_Lynx_Sensei"] = "Нравятся мои узоры? Там, откуда я родом, их набивают сильнейшим в память о военных подвигах. Теперь и ты станешь частью моего рисунка...",
        ["Guard1_Wasp_Sensei"] = "Ты веришь в фортуну? Думаю, сегодня мне крупно повезет — я заберу все твои денежки! Повезет ли тебе, старик?",
        ["Guard1_Widow_Sensei"] = "Госпожа мне как сестра. Я отлично чувствую ее боль. Она запретила мне трогать Князя, поэтому мой гнев падет на тебя!",
        ["Guard2_Butcher_Sensei"] = "Добыча сама идет к хищнику! Философия — это для умников, я же просто люблю играть с ножами. Поиграете со мной?!",
        ["Guard2_Hermit_Sensei"] = "Учитель рассказывал о мире теней, его обитателях и невероятной силе, которой поделится с нами. Думаешь, я позволю все это у нас забрать?",
        ["Guard2_Lynx_Sensei"] = "Наш клан делает работу, о которую даже боги не хотят марать руки. Мы решаем проблемы и исправляем чужие ошибки. И ты — одна из них. ",
        ["Guard2_Wasp_Sensei"] = "Угрожаешь моему капитану? Она спасла меня из рабства, и я поклялась отработать свою свободу. Пусть духи будут добры к тебе...",
        ["Guard2_Widow_Sensei"] = "Моя госпожа прекрасна! Я был не достоин смотреть на ее лик... Теперь моя жизнь принадлежит ей. Я буду защищать ее честь до последнего вздоха.",
        ["HermitYoung_Greetings"] = "Князь, вы — жертва обстоятельств. Ее нужно было принести для общего блага. Моя школа станет великой, и настанет золотой век боевых искусств!",
        ["Hermit_zone2_1"] = "Вы оказались между молотом и наковальней, господин. Да, я предал вас. У меня не было выбора, ведь на карту поставлено будущее моей школы.",
        ["Hermit_zone2_2"] = "Этот заносчивый юнец Рысь не справился со своей задачей. Видимо, его работу придется делать мне. Ученики, сюда!",
        ["LynxYoung_Greetings"] = "Я не могу просто так уйти. Я уже взял деньги за жизнь Князя. Ничего личного, старик.",
        ["Lynx_Sensei_1"] = "Не слушай Князя, старик, он сошел с ума. Мы отведем его высочество домой, пока он не навредил себе. Твоя помощь не требуется.",
        ["Lynx_Sensei_2"] = "Правда? А вот я вижу напуганного человека в окружении головорезов. Что-то подсказывает мне, что Князь говорит правду. Отойдите от него!",
        ["Lynx_Sensei_3"] = "Дело твое. За разговоры мне не платят. Две головы — больше денег! Взять их, ребята!",
        ["NAME_BUTCHER"] = "МЯСНИК",
        ["NAME_HERMIT"] = "ОТШЕЛЬНИК",
        ["NAME_LYNX"] = "РЫСЬ",
        ["NAME_PRINCE"] = "КНЯЗЬ",
        ["NAME_SHOGUN"] = "СЕГУН",
        ["NAME_WASP"] = "ОСА",
        ["NAME_WIDOW"] = "ВДОВА",
        ["OK"] = "ОК",
        ["Prince_Intro"] = "Спасите! Эти люди хотят меня убить!",
        ["Prince_zone3_1"] = "Как ты смеешь очернять мое имя! Ты... ты жалкий отброс! Я вернулся, чтобы положить конец твоему царству жестокости!",
        ["Prince_zone6_1"] = "Вот и ты, мой верный друг! Смотри, справедливость вновь торжествует — Сегун предан мне словно пес! Его разум принадлежит мне!",
        ["Prince_zone6_2"] = "Ты тоже хочешь забрать мой трон, старик?! Он принадлежит мне по праву рождения! Никто не заберет его!",
        ["Sensei_arc_intro1"] = "Однажды во время прогулки я встретил правителя местных земель, которому угрожала смертельная опасность.",
        ["Sensei_zone3_1"] = "Значит, вот так работает \"удача\"? Купили себе свободу, бросили людей на растерзание банде безумцев... А я был добр к вам, Князь.",
        ["Sensei_zone4_1"] = "Вдова? Конечно... она приказала мне забрать Сферу и доставить ее  Сегуну лично в руки.",
        ["Sensei_zone6_1"] = "Остановись, Князь! Посмотри вокруг! Эта Сфера питается твоей яростью, она превращает тебя в чудовище!",
        ["Shogun_zone6_1"] = "Слабак! Ты не годишься даже в шуты при дворе моего повелителя. Я сокрушу тебя одним ударом!",
        ["TITLE_PRINCE_EVIL"] = "ПРОКЛЯТЫЙ ПРИНЦ",
        ["WaspYoung_Greetings"] = "Что я скажу своему отцу? Что его дочь размякла и проиграла бой какому-то старику? Не бывать этому, пока я — наследница пиратского трона!",
        ["Wasp_zone4_1"] = "Вдова прислала тебя забрать Сферу? А не староват ли ты для такого рода поручений? Хотя какое мне дело. Поднимайся на борт.",
        ["Wasp_zone4_2"] = "Только вот Сферы у меня больше нет. Люди Вдовы забрали ее еще вчера. Уж не знаю, кто ты, но ложь я не прощаю. Протащить его под килем!",
        ["WidowYoung_Greetings"] = "Князь унизил меня, отверг, посмеялся над моими чувствами. И теперь я ударю в ответ! Ты — его друг, поэтому передашь от меня это послание...",
        ["Widow_zone5_1"] = "Ты тоже пришел унизить меня, как и Князь? Вы, мужчины, все одинаковые...",
        ["Widow_zone5_2"] = "Он рассказывал о твоем добром нраве, о чести, достоинстве. Но больше я мужским словам не верю. Каждый из вас будет страдать!",
        ["Zone2_SenseiReminder"] = "В прошлый раз я поведал о том, как спас Князя от убийц. Я узнал, что солдаты Князя в тайне обучаются у Отшельника. И мы направились к нему.",
        ["Zone3_SenseiReminder"] = "Отшельник поведал, что Князя предал военачальник Сегун и заплатил некому Мяснику за похищение правителя. Время навестить бандита.",
        ["Zone4_SenseiReminder"] = "В злоключениях Князя виновата женщина! Она придумала, как сбросить правителя с трона с помощью магической Сферы, которую доставили в порт...",
        ["Zone5_SenseiReminder"] = "Пиратка рассказала мне о непростых отношениях Вдовы и Князя. Я не получил Сферу, но узнал, что Князь направился в горы, чтобы найти Вдову.",
        ["Zone6_SenseiReminder"] = "Магическая Сфера свела Князя с ума! Он обрел невероятную силу, которая грозила погубить нас всех! Я не мог этого допустить!",
