        ["character_Pirate"] = "PIRAT",
        ["character_Ronin"] = "BÅDBRINGARE",
        ["character_Sadist"] = "PLÅGA",
        ["character_Savage"] = "GNISTA",
        ["character_Sister"] = "ASTER",
        ["dlgStoryBtnFight"] = "STRID!",
    },
    tur = {
        ["ActScreenSensei1"] = "Sensey'in Öyküsü{br}1. Kısım. Şahit",
        ["ActScreenSensei2"] = "Sensey'in Öyküsü{br}2. Kısım. Geleceğin Gölgesi",
        ["ActScreenSensei3"] = "Sensey'in Öyküsü{br}3. Kısım. İçindeki Yaratık",
        ["ActScreenSensei4"] = "Sensey'in Öyküsü{br}4. Kısım. İntikam Öyküsü",
        ["ActScreenSensei5"] = "Sensey'in Öyküsü{br}5. Kısım. Ezilenler",
        ["ActScreenSensei6"] = "Sensey'in Öyküsü{br}6. Kısım. Canavar",
        ["ButcherYoung_Greetings"] = "Hiç kimse otoritemden şüphe duymaya cüret edemez! Aile bunu hiçbir zaman unutmaz. Canlı çıkamayacaksın!",
        ["Butcher_zone3_1"] = "Kayıp çocuk döndü! Teklifimi düşündün mü, Prens? Ben seni serbest bırakıp Küre'nin yerini söylüyorum, sen de bana altın ödüyorsun.",
        ["Butcher_zone3_2"] = "Sessizliği sözlerinden daha büyük anlam taşır, yaşlı adam. Ben-Ben kendime karşı dürüstüm, caniliğimi kabulleniyorum. Ama o kabullenmiyor. Size tevazunun ne anlama geldiğini öğretmeliyiz! Gelin çocuklar!",
        ["Guard1_Butcher_Sensei"] = "Kasap, acının gerçek bizi nasıl ortaya çıkardığını gösterdi. Artık özgürüm! Sen de mutluluğu bulabilirsin. Direnme!",
        ["Guard1_Hermit_Sensei"] = "Değişim kaçınılmazdır! Bunu öğrenmek için dünyanın yarısını aştım, çok fazla şey feda ettim... Elimdeki tek şey Usta'nın bilgeliği!",
        ["Guard1_Lynx_Sensei"] = "Dövmelerimi beğendin mi? Doğduğum bölgede, en güçlüler başarılarının hatıralarını dövmelerinde taşır. Yakında sen de bu hatıraların bir parçası olacaksın...",
        ["Guard1_Wasp_Sensei"] = "Şansa inanır mısın? Bugünkü harçlığımı ihtiyarın tekinden çıkartacağım için oldukça şanslıyım. Şansına küs ihtiyar. ",
        ["Guard1_Widow_Sensei"] = "Hanımım benim kardeşim gibidir. Acısını hissedebilirim. Prens'e dokunmam yasak ama sinirimi senden çıkartmama kimse engel olmayacak!",
        ["Guard2_Butcher_Sensei"] = "Zafer çantada keklik! Felsefe ezikler içindir—bense sadece bıçaklarla oynamayı severim. Benimle oynamak ister misin?",
        ["Guard2_Hermit_Sensei"] = "Ustamız bize gölgeler dünyasından; oranın sakinlerinden ve bizimle paylaşacağı o muazzam güçten bahsetti. Tüm bunları elimizden almana izin vereceğimi mi sanıyorsun?",
